    customDomainAddresses?: readonly string[];
    /** Secret embedded in the private Caddy on-demand TLS permission URL. */
    tlsAskToken?: string;
    timeoutMs?: number;
    maxBodyBytes?: number;
    resolveTxt?: (hostname: string) => Promise<readonly (readonly string[])[]>;
